// Fails if an exported declaration or class member in the published .d.ts files has no
// doc comment. Usage: node scripts/check-dts-docs.mjs [files…] (default: wasm + dist).
import { readFile, readdir } from 'node:fs/promises';

const root = new URL('..', import.meta.url);
const defaults = async () => [
  new URL('wasm/laserline.d.ts', root),
  ...(await readdir(new URL('dist/', root))).filter((f) => f.endsWith('.d.ts')).map((f) => new URL(`dist/${f}`, root)),
];
const files = process.argv.length > 2 ? process.argv.slice(2) : await defaults();

// Generated by wasm-bindgen for its loader, or private: not part of the documented API.
const IGNORE = /^(export (\{|type \{|\* )|export (default |type InitInput|interface InitOutput|type SyncInitInput|function initSync)|\s+(free|\[Symbol\.dispose\]|private |protected ))/;
const DECL = /^(export (declare )?(function|class|interface|type|const|enum|abstract class) |\s+(readonly |static |get |set )*[A-Za-z_$][\w$]*\??(\(|:| \())/;

const missing = [];
for (const file of files) {
  const lines = (await readFile(file, 'utf8')).split('\n');
  let inInitOutput = false;
  let inTypeAlias = false;
  let depth = 0;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^export interface InitOutput\b/.test(line)) inInitOutput = true;
    if (inInitOutput) {
      if (/^}/.test(line)) inInitOutput = false;
      continue;
    }
    // Members of object types nested in a declaration, or of the object types of a type
    // alias (e.g. message unions), are documented by their parent.
    if (depth === 0) inTypeAlias = /^export (declare )?type \w+(<.*>)? =/.test(line);
    const nested = depth > 1 || (inTypeAlias && depth > 0);
    depth += (line.match(/{/g) ?? []).length - (line.match(/}/g) ?? []).length;
    if (nested || !DECL.test(line) || IGNORE.test(line)) continue;
    let j = i - 1;
    while (j >= 0 && /^\s*(@|\/\/)/.test(lines[j])) j--;
    // A setter shares the doc of its getter.
    if (/^\s+set /.test(line) && /^\s+get /.test(lines[j] ?? '')) continue;
    if (!/\*\/\s*$/.test(lines[j] ?? '')) missing.push(`${String(file).replace(root.href, '')}:${i + 1}: ${line.trim()}`);
  }
}
if (missing.length) {
  console.error(`${missing.length} undocumented declarations:\n${missing.join('\n')}`);
  process.exit(1);
}
console.log(`${files.length} declaration files documented`);
